function render({ props, frame }) {
  // A tiny deterministic heatmap: one rect per series value, wrapping into
  // rows of 13, intensity = value / max. Pure function of (props, frame).
  var values = Array.isArray(props.values) ? props.values : [];
  var cols = 13;
  var gap = 4;
  var cell = 14;
  var top = 24;
  var count = Math.min(values.length, 128);
  var nodes = [
    {
      id: "label",
      type: "text",
      x: 0,
      y: 0,
      w: frame.w,
      h: 16,
      text: props.label,
      style: { fontSize: 12, color: "#7d8590" }
    }
  ];
  function at(i) {
    var v = values[i];
    return typeof v === "number" && isFinite(v) && v > 0 ? v : 0;
  }
  var max = 0;
  for (var i = 0; i < count; i++) {
    if (at(i) > max) max = at(i);
  }
  for (var j = 0; j < count; j++) {
    var t = max > 0 ? at(j) / max : 0;
    var col = j % cols;
    var row = (j - col) / cols;
    nodes.push({
      id: "cell-" + j,
      type: "rect",
      x: col * (cell + gap),
      y: top + row * (cell + gap),
      w: cell,
      h: cell,
      opacity: t === 0 ? 1 : Math.min(1, 0.3 + 0.7 * t),
      style: { fill: t === 0 ? "#161b22" : props.accent, radius: 3 }
    });
  }
  return nodes;
}
